/* film-pal.js: this film's own colours. The demo uses the house palette as it is, so nothing is added.
 * A film adds its colours here with Object.assign(HOUSE.pal, { … }) (see templates/video/story/film-pal.js).
 */
(function () {
  const HOUSE = (window.HOUSE = window.HOUSE || {});
  Object.assign(HOUSE.pal, {});
})();
